import test from 'node:test';
import assert from 'node:assert/strict';
const api=await import('../src/ceo-source-approval-readiness.js').catch(()=>({}));
function draft(){assert.equal(typeof api.buildCeoOperationalApprovalRequest,'function');return api.buildCeoOperationalApprovalRequest({schema:'ceo-workbuddy-operational-entry/v1',sourceMode:'REAL_READ_ONLY',reportId:'ceo-op-example',batchId:'aeb-example',sourceReportHash:'a'.repeat(64),storeObservation:{envId:'400370',channelId:'2358891',envName:'纳物-箱包全托1店'},evidence:{sourceHash:'b'.repeat(64),collectorHash:'c'.repeat(64)},versionBindings:{files:{'config/metrics-schema.json':'d'.repeat(64)}},entryRuntime:{fingerprint:'e'.repeat(64)},statuses:{backendConnection:{status:'CONNECTED'},collection:{status:'COMPLETE'},metricTrust:{status:'CHECKED_WITH_GAPS'},storeIdentityApproval:{status:'UNVERIFIED'},humanApproval:{status:'UNAPPROVED'}},facts:[]});}
test('approval preparation is a draft, never a reviewer registration or approval',()=>{const r=draft();assert.equal(r.status,'DRAFT');assert.equal(r.humanReviewer,null);assert.equal(r.approvalRef,null);assert.equal(r.registerReviewer,false);assert.equal(r.formalContextStatus,'NOT_ELIGIBLE');});
test('minimal authority records preserve unapproved store identity and money period',()=>{const r=draft();assert.equal(r.authorityRecord.platformShopId,null);assert.equal(r.authorityRecord.status,'UNVERIFIED');assert.equal(r.periodAuthority.amountPeriod,'UNVERIFIED_PERIOD');assert.equal(r.periodAuthority.timezoneOffset,null);});
test('approval request binds exact observed report, collector, dictionary and entry runtime',()=>{const r=draft();assert.equal(r.evidence.reportHash,'a'.repeat(64));assert.equal(r.versionBindings.files['config/metrics-schema.json'],'d'.repeat(64));assert.equal(r.entryRuntime.fingerprint,'e'.repeat(64));});
test('deployment, schedules, tasks and Workflow remain outside data approval',()=>{const r=draft();assert.equal(r.deploymentApproval,'NOT_APPROVED');assert.deepEqual(r.businessWriteAuthority,[]);assert.equal(r.automaticScheduling,false);assert.ok(r.humanDecisions.length>=4);});
test('connection completeness and trust remain five independent checklist statuses',()=>{const r=draft();assert.equal(Object.keys(r.observedStatuses).length,5);assert.equal(r.observedStatuses.humanApproval.status,'UNAPPROVED');});
